<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {createReport,deleteReport,getReports,getReportTypes,reportUrl,type ReportRecord} from '@/api/reports'
import {getTyphoons} from '@/api/typhoons'
import {getExperiments} from '@/api/ml'
const types=ref<any[]>([]),reports=ref<ReportRecord[]>([]),typhoons=ref<any[]>([]),experiments=ref<any[]>([]),loading=ref(false),preview=ref(''),previewOpen=ref(false),statusFilter=ref(''),typeFilter=ref('')
const form=ref({report_type:'typhoon',title:'',typhoon_id:undefined as number|undefined,experiment_id:undefined as string|undefined,force:false})
const successfulExperiments=computed(()=>experiments.value.filter(x=>x.status==='succeeded'))
const filteredReports=computed(()=>reports.value.filter(x=>(!statusFilter.value||x.report_status===statusFilter.value)&&(!typeFilter.value||x.report_type===typeFilter.value)))
const canSubmit=computed(()=>form.value.report_type==='typhoon'?!!form.value.typhoon_id:form.value.report_type==='model'?!!form.value.experiment_id:true)
let timer:number|undefined
async function refresh(){reports.value=await getReports()}
async function submit(){if(!canSubmit.value)return ElMessage.warning('请选择报告所需的数据范围');loading.value=true;try{await createReport(form.value);ElMessage.success('报告任务已创建');await refresh()}catch(e:any){ElMessage.error(e.response?.data?.message||'报告生成任务创建失败')}finally{loading.value=false}}
async function remove(row:ReportRecord){await ElMessageBox.confirm('删除该报告及其生成文件？','二次确认',{type:'warning'});await deleteReport(row.id);await refresh()}
function show(row:ReportRecord){preview.value=reportUrl(row.id,'preview');previewOpen.value=true}
function statusType(status:string){return status==='succeeded'?'success':status==='failed'?'danger':'warning'}
onMounted(async()=>{loading.value=true;try{[types.value,reports.value,typhoons.value,experiments.value]=await Promise.all([getReportTypes(),getReports(),getTyphoons({page:1,page_size:100,sort_by:'maximum_wind',sort_order:'desc'}).then(x=>x.items),getExperiments()]);timer=window.setInterval(refresh,2500)}finally{loading.value=false}})
onBeforeUnmount(()=>timer&&clearInterval(timer))
</script>
<template><section v-loading="loading" class="page-stack"><div class="page-heading"><h2>科研分析报告中心</h2><el-button @click="refresh">刷新</el-button></div>
<el-card shadow="never"><template #header><strong>新建报告</strong></template><el-form label-position="top" class="report-form"><el-form-item label="报告类型"><el-select v-model="form.report_type"><el-option v-for="x in types" :key="x.code" :label="x.name" :value="x.code"/></el-select></el-form-item><el-form-item label="自定义标题"><el-input v-model="form.title" maxlength="200" placeholder="留空使用默认标题"/></el-form-item><el-form-item v-if="form.report_type==='typhoon'" label="历史台风"><el-select v-model="form.typhoon_id" filterable placeholder="请选择台风"><el-option v-for="x in typhoons" :key="x.id" :label="`${x.sid} · ${x.name}`" :value="x.id"/></el-select></el-form-item><el-form-item v-if="form.report_type==='model'" label="正式实验"><el-select v-model="form.experiment_id" filterable placeholder="请选择实验"><el-option v-for="x in successfulExperiments" :key="x.id" :label="`${x.name} · ${x.model_type.toUpperCase()}`" :value="x.id"/></el-select></el-form-item><el-form-item><el-checkbox v-model="form.force">数据未变化时仍重新生成</el-checkbox></el-form-item><el-form-item><el-button type="primary" :disabled="!canSubmit" @click="submit">生成报告</el-button></el-form-item></el-form></el-card>
<el-card shadow="never"><template #header><div class="card-header"><strong>报告记录</strong><div class="inline-controls"><el-select v-model="typeFilter" clearable placeholder="全部类型" style="width:160px"><el-option v-for="x in types" :key="x.code" :label="x.name" :value="x.code"/></el-select><el-select v-model="statusFilter" clearable placeholder="全部状态" style="width:130px"><el-option label="已完成" value="succeeded"/><el-option label="生成中" value="generating"/><el-option label="失败" value="failed"/></el-select><el-button @click="refresh">刷新</el-button></div></div></template><el-table :data="filteredReports" empty-text="尚未生成报告"><el-table-column prop="report_title" label="标题" min-width="250"/><el-table-column prop="report_type" label="类型" width="130"/><el-table-column prop="created_at" label="创建时间" width="185"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.report_status)">{{row.report_status==='succeeded'?'已完成':row.report_status==='generating'?'生成中':row.report_status==='failed'?'失败':'排队中'}}</el-tag></template></el-table-column><el-table-column label="操作" width="290"><template #default="{row}"><el-button link :disabled="row.report_status!=='succeeded'" @click="show(row)">预览</el-button><el-link :href="reportUrl(row.id,'html')" :disabled="row.report_status!=='succeeded'">HTML</el-link><el-link :href="reportUrl(row.id,'pdf')" :disabled="row.report_status!=='succeeded'">PDF</el-link><el-button link type="danger" :disabled="['queued','generating'].includes(row.report_status)" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="previewOpen" width="86%" title="报告预览" destroy-on-close><iframe class="report-preview" :src="preview" title="科研报告预览"/></el-dialog></section></template>
